.cta-orb.g { background: var(--orb-green); bottom: -60px; right: -40px; }

/* Footer */
.site-footer { background: var(--ink-dark); color: rgba(255,255,255,0.72); padding: 48px 0 0; position: relative; z-index: 1; }
.ft-top { display: flex; justify-content: space-between; gap: 32px; flex-wrap: wrap; padding-bottom: 28px; border-bottom: 1px solid rgba(255,255,255,0.08); }
.ft-brand { max-width: 440px; }
.ft-brand p { color: rgba(255,255,255,0.5); max-width: 410px; margin-top: 10px; text-wrap: pretty; }
