.socials { display: flex; gap: 12px; margin-top: 16px; }
.news { display: flex; gap: 8px; align-items: center; width: 100%; max-width: 400px; }
.news input {
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); color: #fff;
  padding: 10px 16px; border-radius: var(--radius-pill); min-width: 0; flex: 1 1 auto;
  font-size: 14px; line-height: 1.4; box-shadow: var(--shadow-inset);
}
.news .btn { padding: 10px 22px; font-size: 14px; white-space: nowrap; flex-shrink: 0; }
.ft-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px; padding: 28px 0; }
.ft-grid h4 { color: #fff; font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; margin-bottom: 12px; }
.ft-grid a { display: block; font-size: 13.5px; padding: 4px 0; color: rgba(255,255,255,0.55); transition: color var(--duration-fast); }
.ft-grid a:hover { color: #fff; }
.ft-nav { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; padding: 28px 0; }
.ft-nav > div { display: flex; flex-direction: column; align-items: flex-start; }
.ft-nav > div:last-child { align-items: flex-end; text-align: right; }
.ft-nav a { display: block; font-size: 13.5px; padding: 4px 0; color: rgba(255,255,255,0.55); transition: color var(--duration-fast); }
