@media (max-width: 640px) { .ft-nav { grid-template-columns: 1fr; } }
.ft-bot { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 16px 0 20px; border-top: 1px solid rgba(255,255,255,0.08); font-size: 13px; }
.ft-bot a:hover { color: #fff; }
.site-footer .container { container-type: inline-size; }
.ft-giant { color: #ffffff; font-weight: 800; font-size: clamp(2.4rem, 8.5vw, 7.5rem); font-size: 10.8cqw; line-height: 0.95; letter-spacing: -0.02em; text-align: left; text-transform: uppercase; padding: 6px 0 26px; user-select: none; white-space: nowrap; overflow: hidden; }
@media (max-width: 640px) { .ft-giant { white-space: normal; line-height: 1; } }

/* Forms */
.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; font-size: 14px; font-weight: 500; }
.field input, .field textarea, .field select {
  background: #fff; border: 1px solid #D9D9D4; border-radius: 12px;
  padding: 13px 15px; box-shadow: var(--shadow-inset); font-size: 15px; font-weight: 400; color: var(--ink);
  transition: border-color var(--duration-fast), box-shadow var(--duration-fast);
}
.field input:focus, .field textarea:focus, .field select:focus {
  outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(84,76,217,0.12);
}
.field.error input { border-color: #c0392b; animation: shake 0.4s; }
@keyframes shake { 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
.row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
/* Contact form: single even rhythm, no doubled margins inside the 2-col row */
#consult-form .field { margin-bottom: 16px; }
#consult-form .row-2 { gap: 16px; margin-bottom: 16px; }
#consult-form .row-2 .field { margin-bottom: 0; }
#consult-form #step-2 .pills { margin-bottom: 16px; }
#consult-form #step-2 label.field { margin-top: 0; }
.pills { display: flex; flex-wrap: wrap; gap: 8px; }
.pill-opt {
  border: 1px solid var(--light-gray); border-radius: var(--radius-pill); padding: 8px 14px; font-size: 13px; font-weight: 500; cursor: pointer;
}
.pill-opt:has(input:checked) { border-color: var(--accent); background: rgba(84,76,217,0.08); color: var(--accent); }
.pill-opt input { position: absolute; opacity: 0; pointer-events: none; }
.steps { display: flex; align-items: center; gap: 10px; margin-bottom: 22px; }
.step-dot { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700; border: 1px solid var(--light-gray); }
.step-dot.on { background: var(--accent); color: #fff; border-color: var(--accent); }
.step-line { flex: 1; height: 2px; background: var(--light-gray); }
.hidden { display: none !important; }
.success-check { width: 72px; height: 72px; margin: 0 auto 16px; }
.success-check circle { fill: none; stroke: var(--green); stroke-width: 2; }
.success-check path { fill: none; stroke: var(--green); stroke-width: 3; stroke-linecap: round; stroke-dasharray: 48; stroke-dashoffset: 48; animation: draw 0.8s 0.2s forwards var(--ease-out-expo); }
@keyframes draw { to { stroke-dashoffset: 0; } }

/* Pages extras */
.breadcrumb { font-size: 13px; color: var(--mid-gray); padding: 20px 0 0; }
.breadcrumb a:hover { color: var(--accent); }
/* Service pages: daylight between blurb and CTA buttons. */
.page-hero .hero-ctas { margin-top: 22px; }
/* Service pages: roomier "What it is" prose (scoped to sections with svc art). */
.two-col:has(.svc-side) > div > p { line-height: 1.8; margin-bottom: 16px; }
.page-hero { padding: 36px 0 18px; }
.page-hero h1 { font-size: clamp(1.98rem, 4.5vw, 3.6rem); margin: 10px 0 12px; }
.insights-hero { min-height: calc(100vh - var(--announce-h) - var(--nav-h)); display: grid; align-items: center; padding: 48px 0; }
.insights-list { padding-top: 8px; }
.kpis-row { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 16px; }
.kpis-row .glass-card { padding: 12px 16px; font-size: 13px; }
.kpis-row strong { display: block; font-size: 16px; }

.timeline { position: relative; padding-left: 152px; }
.timeline::before {
  content: ""; position: absolute; left: 120px; top: 0; bottom: 0; width: 2px;
  background: linear-gradient(var(--accent), var(--blue)); transform: scaleY(0); transform-origin: top;
  transition: transform 1.4s var(--ease-out-expo);
}
.timeline.in::before { transform: scaleY(1); }
.tl-row { display: grid; grid-template-columns: 112px 1fr; gap: 40px; margin-left: -152px; padding: 18px 0; position: relative; }
.tl-row .yr { font-weight: 700; color: var(--ink); padding-right: 12px; }
.tl-row::after {
  content: ""; position: absolute; left: 115px; top: 26px; width: 12px; height: 12px; border-radius: 50%;
  background: #fff; border: 2px solid var(--accent);
}

.team-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; max-width: 880px; }
.team-grid > :only-child { grid-column: 1 / -1; }
.team-card { padding: 24px; text-align: center; position: relative; }
.team-card .av { width: 88px; height: 88px; border-radius: 50%; margin: 0 auto 14px; background: linear-gradient(135deg, var(--accent), var(--blue)); }
/* Single-founder feature card: photo left, content right. */
.team-card.team-side { display: flex; gap: 28px; align-items: center; text-align: left; }
.team-card.team-side .av-photo { width: 200px; height: 250px; object-fit: cover; border-radius: 14px; flex: 0 0 auto; display: block; }
.team-card.team-side .team-body { flex: 1 1 auto; min-width: 0; }
@media (max-width: 640px) {
  .team-card.team-side { flex-direction: column; text-align: center; }
  .team-card.team-side .av-photo { width: 180px; height: 225px; }
}
.hover-extra { opacity: 0; transition: opacity var(--duration-base); font-size: 13px; font-style: italic; color: var(--mid-gray); }
.team-card:hover .hover-extra { opacity: 1; }
/* Flip founder cards: front mirrors the reference (role top-right, round photo,
   name bottom-left, arrow bottom-right); arrow flips to intro + website link. */
.flip-card { perspective: 1400px; }
.flip-inner { position: relative; transform-style: preserve-3d; transition: transform 0.7s var(--ease-out-expo); }
.flip-card.flipped .flip-inner { transform: rotateY(180deg); }
.flip-face { backface-visibility: hidden; -webkit-backface-visibility: hidden; border-radius: var(--radius-lg); overflow: hidden; padding: 32px; }

