.values { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.life-bar { display: flex; align-items: center; gap: 0; overflow-x: auto; padding-bottom: 8px; }
.life-node { display: flex; flex-direction: column; align-items: center; min-width: 120px; text-align: center; gap: 6px; font-size: 13px; font-weight: 600; }
.life-node .dot { width: 14px; height: 14px; border-radius: 50%; background: linear-gradient(90deg, var(--accent), var(--blue)); }
.life-line { flex: 1; height: 3px; min-width: 40px; background: linear-gradient(90deg, var(--accent), var(--blue)); opacity: 0.45; }
.svc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.svc-card { padding: 20px; display: block; }
.svc-card:hover { border-color: var(--accent); box-shadow: var(--shadow-lg), var(--shadow-glow-accent); }
.svc-card .arrow { display: inline-block; transition: transform var(--duration-fast); }
.svc-card:hover .arrow { transform: translateX(6px); }
.phase-div { text-align: center; color: var(--mid-gray); font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; padding: 8px 0; border-top: 1px solid var(--light-gray); }

.process { position: relative; }
.step { display: grid; grid-template-columns: 48px 1fr; gap: 14px; margin: 14px 0; position: relative; }
.step .num { width: 36px; height: 36px; border-radius: 50%; background: var(--accent); color: #fff; display: grid; place-items: center; font-weight: 700; z-index: 1; }
.process::before { content: ""; position: absolute; left: 17px; top: 10px; bottom: 10px; border-left: 1.5px dashed var(--light-gray); }
.who-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.deliverables { padding: 26px; }
.check-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 14px; }
.check-grid li { display: flex; gap: 8px; } .check-grid i { color: #059669; }
.check-grid li.grphead { grid-column: 1 / -1; font-weight: 600; color: var(--ink); margin-top: 6px; }
.check-grid li.grphead:first-child { margin-top: 0; }
.deliverables-dark .check-grid li.grphead { color: #fff; }
/* Service pages: full-width tinted band breaks the card-stack rhythm. */
.section.band { background: var(--off-white); border-block: 1px solid var(--light-gray); }
/* Service pages: dark deliverables panel, same inks as the footer. */
.deliverables-dark { background: var(--ink-dark); border-color: transparent; color: #fff; }
.deliverables-dark h2 { color: #fff; }
.deliverables-dark .check-grid li { color: rgba(255,255,255,0.82); }
.deliverables-dark .check-grid i { color: var(--green); }

.faq-item { border-bottom: 1px solid var(--light-gray); }
.faq-item button { width: 100%; display: flex; justify-content: space-between; padding: 16px 0; font-weight: 600; text-align: left; }
.faq-item .plus { transition: transform var(--duration-base); }
.faq-item.open .plus { transform: rotate(45deg); }
.faq-item .ans { max-height: 0; overflow: hidden; transition: max-height var(--duration-base) var(--ease-out-expo); color: var(--mid-gray); }
.faq-item.open .ans { max-height: 240px; padding-bottom: 14px; }

.filters { display: flex; flex-wrap: wrap; gap: 8px; margin: 14px 0 20px; }
.filter {
  padding: 8px 14px; border-radius: var(--radius-pill); background: var(--light-gray); font-size: 13px; font-weight: 600; color: var(--dark-gray);
}
.filter.active { background: var(--accent); color: #fff; }
.case-grid, .tools-stack { display: grid; gap: 18px; }
.case-grid { grid-template-columns: repeat(2, 1fr); }
.case-card { padding: 24px; }
.metrics3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 12px 0; text-align: center; }
.metrics3 .n { font-weight: 700; background: linear-gradient(90deg, var(--accent), var(--blue)); -webkit-background-clip: text; background-clip: text; color: transparent; font-size: 1.2rem; }
/* Case deck: six portrait playing cards fanned in one tight row, close blue
   shades, subtle individual tilts; hovered card comes to the front. */
.case-deck { display: flex; align-items: stretch; margin-top: 40px; padding: 24px 12px 30px; }
.case-deck .case-card { flex: 1 1 0; min-width: 0; margin-left: -30px; border: 0; border-radius: 18px; padding: 30px 24px; display: flex; flex-direction: column; min-height: 540px; color: #fff; position: relative; transform: rotate(var(--tilt, 0deg)); transition: transform 0.45s var(--ease-out-expo), box-shadow 0.45s var(--ease-out-expo); box-shadow: 0 12px 32px rgba(10,20,80,0.25); }
.case-deck .case-card:first-child { margin-left: 0; }
.case-deck .case-card:nth-child(1) { --tilt: -2deg; background: #101FA8; z-index: 1; }
.case-deck .case-card:nth-child(2) { --tilt: -1.2deg; background: #1629C4; z-index: 2; }
.case-deck .case-card:nth-child(3) { --tilt: -0.4deg; background: #1B30D6; z-index: 3; }
.case-deck .case-card:nth-child(4) { --tilt: 0.4deg; background: #2036E6; z-index: 4; }
.case-deck .case-card:nth-child(5) { --tilt: 1.2deg; background: #273EF2; z-index: 5; }
.case-deck .case-card:nth-child(6) { --tilt: 2deg; background: #3049FA; z-index: 6; }
.case-deck .case-card:hover { transform: rotate(0deg) translateY(-12px); z-index: 30; box-shadow: 0 28px 64px rgba(10,20,80,0.4); }
.deck-eyebrow { font-size: 11px; letter-spacing: 0.14em; font-weight: 600; text-transform: uppercase; color: rgba(255,255,255,0.65); }
.case-deck .case-card h3 { font-family: 'IvyPresto Display Light','IvyPresto Regular','Cormorant Garamond',Georgia,serif; font-weight: 300; font-size: 1.5rem; line-height: 1.3; color: #fff; margin: 12px 0 18px; }
.case-deck .metrics3 { grid-template-columns: 1fr; text-align: left; gap: 14px; margin: 0 0 22px; }
.case-deck .metrics3 .n { background: none; color: #fff; font-size: 1.35rem; }
.case-deck .metrics3 .l { color: rgba(255,255,255,0.72); font-size: 12.5px; }
.deck-link { margin-top: auto; width: max-content; color: #fff; font-weight: 600; font-size: 14px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.5); }
@media (max-width: 900px) {
  .case-deck { flex-direction: column; }
  .case-deck .case-card { margin-left: 0; margin-top: 16px; min-height: 0; transform: none; }
  .case-deck .case-card:first-child { margin-top: 0; }
}

