.svc-timeline.show-all .tl-card { transition-delay: 0ms !important; }
.tl-phase.lit .tl-card:hover, .svc-timeline.show-all .tl-card:hover { transform: translateY(-2px); background: linear-gradient(180deg, rgba(84,76,217,0.08), rgba(2,104,232,0.07)); border-color: rgba(84,76,217,0.32); }
.tl-card-name { color: var(--ink); font-size: 0.98rem; font-weight: 600; line-height: 1.4; font-family: 'Inter','Helvetica','Roboto','Poppins',sans-serif; }
.tl-card-blurb { color: var(--text-body); font-size: 0.85rem; line-height: 1.55; }
.tl-card-go { margin-top: auto; padding-top: 10px; font-size: 0.85rem; font-weight: 500; color: var(--mid-gray); }
.tl-card-go > span { display: inline-block; transition: transform var(--duration-fast) var(--ease-out-expo); }
.tl-card:hover .tl-card-go { color: var(--accent); }
.tl-card:hover .tl-card-go > span { transform: translate(2px, -2px); }
.tl-card:focus { outline: none; }
.tl-card:focus-visible { outline: none; border-color: rgba(84,76,217,0.5); background: linear-gradient(180deg, rgba(84,76,217,0.08), rgba(2,104,232,0.07)); }
.tl-card:focus-visible .tl-card-go { color: var(--accent); }
.tl-card[hidden] { display: none !important; }
@media (max-width: 900px) {
  .svc-util { grid-template-columns: 1fr; }
  .svc-util .svc-search { max-width: 100%; }
}
@media (max-width: 640px) {
  .tl-rail { display: none; }
  .tl-head { max-width: none; padding-left: 0; }
  .tl-car { padding-left: 0; }
  .tl-track > .tl-card:nth-child(odd) { --tx: -16px; }
  .tl-track > .tl-card:nth-child(even) { --tx: 16px; }
  .svc-timeline { padding-top: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  [data-animate] { opacity: 1; transform: none; transition: none; }
  .tiltable { transform: none; }
  .tl-card { opacity: 1; transform: none; transition: background 0.3s, border-color 0.3s; }
  .tl-phase.lit .tl-card { transition-delay: 0ms; }
  .tl-track { transition: none; }
  [data-animate="mask"] { clip-path: none; transition: none; }
  .hero h1, .page-hero h1, .article-body h1 { animation: none; }
}

