input.newString:
@media (prefers-reduced-motion: reduce) {
  [data-animate] { opacity: 1; transform: none; transition: none; }
  .tiltable { transform: none; }
  .tl-card { opacity: 1; transform: none; transition: background 0.3s, border-color 0.3s; }
  .tl-phase.lit .tl-card { transition-delay: 0ms; }
  .tl-track { transition: none; }
  [data-animate="mask"] { clip-path: none; transition: none; }
  .hero h1, .page-hero h1, .article-body h1 { animation: none; }
}

/* ---- Service pages: editorial, box-free system ----
   Kept boxy on purpose: Related services (.svc-card), FAQ (.faq-item),
   What-it-is art (.svc-side). Everything below is hairlines + type. */
.svc-meta { display: flex; flex-wrap: wrap; gap: 8px 28px; margin-top: 20px; padding: 14px 0; border-top: 1px solid var(--light-gray); border-bottom: 1px solid var(--light-gray); }
.svc-meta span { font-size: 13.5px; color: var(--mid-gray); }
.svc-meta strong { color: var(--ink); font-weight: 600; margin-right: 8px; }
.svc-duo { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-top: 26px; padding-top: 22px; border-top: 1px solid var(--light-gray); }
.svc-duo-item .section-label { margin-bottom: 8px; }
.svc-duo-item strong { display: block; font-size: 1.1rem; line-height: 1.45; font-weight: 600; color: var(--ink); }
.svc-duo-item span { display: block; font-size: 0.9rem; color: var(--mid-gray); margin-top: 6px; line-height: 1.55; }
.ed-list { margin-top: 8px; border-top: 1px solid var(--light-gray); }
.ed-list > li { display: grid; grid-template-columns: 56px 1fr; gap: 18px; padding: 20px 0; border-bottom: 1px solid var(--light-gray); align-items: baseline; }
.ed-num { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 1.1rem; color: #A3A8AE; font-variant-numeric: tabular-nums; }
.ed-list h3 { font-size: 1.05rem; margin-bottom: 4px; }
.ed-list p { font-size: 0.95rem; margin: 0; }
.ed-steps { margin-top: 8px; border-top: 1px solid var(--light-gray); counter-reset: edstep; }
.ed-steps > li { display: grid; grid-template-columns: 56px 1fr; gap: 18px; padding: 18px 0; border-bottom: 1px solid var(--light-gray); align-items: baseline; }
.ed-steps h3 { font-size: 1.05rem; margin-bottom: 4px; }
.ed-steps p { font-size: 0.95rem; margin: 0; }
.ed-who { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; margin-top: 8px; padding-top: 22px; border-top: 1px solid var(--light-gray); }
.ed-who-item small { display: block; font-size: 11px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent); margin-bottom: 10px; }
.ed-who-item p { font-size: 0.92rem; line-height: 1.65; }
.ed-who-item ul { margin-top: 10px; font-size: 0.88rem; color: var(--mid-gray); }
.ed-who-item li { padding: 3px 0; }
.ed-inside { margin-top: 8px; padding-top: 22px; border-top: 1px solid var(--light-gray); }
.ed-inside h2 { margin-bottom: 6px; }
.ed-inside .check-grid { grid-template-columns: 1fr 1fr; }
.ed-inside .check-grid li { font-size: 0.93rem; color: var(--text-body); }
.ed-inside .check-grid li.grphead { font-size: 0.75rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--mid-gray); margin-top: 10px; }
.final-cta.ed-cta { background: var(--off-white); border-top: 1px solid var(--light-gray); text-align: center; }
.final-cta.ed-cta .cta-inner { max-width: 680px; margin: 0 auto; }
.final-cta.ed-cta h2 { margin-bottom: 10px; }
@media (max-width: 768px) {
  .svc-duo { grid-template-columns: 1fr; gap: 20px; }
  .ed-who { grid-template-columns: 1fr; gap: 22px; }
  .ed-list > li, .ed-steps > li { grid-template-columns: 40px 1fr; }
  .ed-inside .check-grid { grid-template-columns: 1fr; }
}

