input.content:
# Box-free redesign codemod for the 37 service pages (ASCII-only, PS 5.1 safe).
# Keeps: Related services (.svc-card), FAQ (.faq-item), What-it-is (.svc-side).
$ErrorActionPreference = 'Stop'
$svcDir = 'C:\Users\ishan\Website\services'
$files = Get-ChildItem (Join-Path $svcDir '*.html') | Sort-Object Name
if ($files.Count -ne 37) { throw ('expected 37 service pages, found ' + $files.Count) }
$errors = New-Object System.Collections.Generic.List[string]
$changed = 0

function Replace-Once([string]$t, [string]$pat, [string]$label, [string]$path, [ref]$out) {
  $n = ([regex]::Matches($t, $pat)).Count
  if ($n -ne 1) { $errors.Add("$path : $label expected 1 match, found $n"); $out.Value = $t; return }
  $out.Value = $t
}

foreach ($f in $files) {
  $path = $f.FullName
  $short = $f.Name
  $t = [System.IO.File]::ReadAllText($path)
  $t = $t -replace "`r`n", "`n"
  $bad = New-Object System.Collections.Generic.List[string]
  $rep = { param($x) return $x }

  # 1. CSS bump
  if (([regex]::Matches($t, '\.\./css/style\.css\?v=13')).Count -ne 1) { $bad.Add('css bump count') }
  $t = $t -replace '\.\./css/style\.css\?v=13', '../css/style.css?v=14'

  # 2. Hero KPI boxes -> hairline meta row
  $km = [regex]::Match($t, '(?s)  <div class="kpis-row">\n((?:    <div class="glass-card">.*?</div>\n)+)  </div>')
  if (-not $km.Success) { $bad.Add('kpis-row block missing') }
  else {
    $items = [regex]::Matches($km.Groups[1].Value, '<div class="glass-card">(.*?)</div>')
    if ($items.Count -ne 3) { $bad.Add(('kpi items=' + $items.Count)) }
    else {
      $inner = ''
      foreach ($it in $items) { $inner += ('    <span>' + $it.Groups[1].Value + "</span>`n") }
      $inner = $inner -replace "`n", "`n"
      $newBlock = ('  <div class="svc-meta">' + "`n" + $inner + '  </div>')
      $t = $t.Substring(0, $km.Index) + $newBlock + $t.Substring($km.Index + $km.Length)
    }
  }

  # 3. Duo boxes -> plain editorial split
  if (([regex]::Matches($t, '<div class="duo-grid" data-stagger>')).Count -ne 1) { $bad.Add('duo-grid count') }
  $t = $t -replace '<div class="duo-grid" data-stagger>', '<div class="svc-duo" data-stagger>'
  if (([regex]::Matches($t, '<div class="glass-card duo"><span class="section-label">When to call us</span>')).Count -ne 1) { $bad.Add('duo-when count') }
  $t = [regex]::Replace($t, '<div class="glass-card duo"><span class="section-label">When to call us</span><strong>(.*?)</strong><span class="duo-sub">(.*?)</span></div>', '<div class="svc-duo-item"><span class="section-label">When to call us</span><strong>$1</strong><span>$2</span></div>')
  if (([regex]::Matches($t, '<div class="svc-duo-item"><span class="section-label">When to call us</span>')).Count -ne 1) { $bad.Add('duo-when replaced') }
  $t = [regex]::Replace($t, '<div class="glass-card duo"><span class="section-label">What you walk away with</span><strong>(.*?)</strong><span class="duo-sub">(.*?)</span></div>', '<div class="svc-duo-item"><span class="section-label">What you walk away with</span><strong>$1</strong><span>$2</span></div>')
  if (([regex]::Matches($t, '<div class="svc-duo-item"><span class="section-label">What you walk away with</span>')).Count -ne 1) { $bad.Add('duo-leaves replaced') }

  # 4. Why band + pillars -> numbered hairline list
  if (([regex]::Matches($t, '<section class="section band">')).Count -ne 1) { $bad.Add('band count') }
  $t = $t -replace '<section class="section band">', '<section class="section">'
  if (([regex]::Matches($t, '<div class="pillars" data-stagger>')).Count -ne 1) { $bad.Add('pillars count') }
  $t = $t -replace '<div class="pillars" data-stagger>', '<ol class="ed-list" data-stagger>'
  $wc = @{ n = 0 }
  $t = [regex]::Replace($t, "<article class='glass-card pillar tiltable'><div class='icon-box'><i data-lucide='[^']*'></i></div><h3>(.*?)</h3><p>(.*?)</p></article>", { param($m) $wc.n++; ("<li><span class='ed-num'>" + ('{0:D2}' -f $wc.n) + "</span><div><h3>" + $m.Groups[1].Value + "</h3><p>" + $m.Groups[2].Value + "</p></div></li>") })
  if ($wc.n -ne 3) { $bad.Add(('why items=' + $wc.n)) }
  if (([regex]::Matches($t, '</div></li>\n  </div>\n</div></section>')).Count -ne 1) { $bad.Add('why-close count') }
  $t = $t -replace '</div></li>\n  </div>\n</div></section>', '</div></li>\n  </ol>\n</div></section>'

  # 5. Process -> numbered hairline list
  if (([regex]::Matches($t, '<div class="process" data-stagger>')).Count -ne 1) { $bad.Add('process count') }
  $t = $t -replace '<div class="process" data-stagger>', '<ol class="ed-steps" data-stagger>'
  $pc = @{ n = 0 }
  $t = [regex]::Replace($t, '<div class="step"><div class="num">\d+</div><div><h3>(.*?)</h3><p>(.*?)</p></div></div>', { param($m) $pc.n++; ("<li><span class='ed-num'>" + ('{0:D2}' -f $pc.n) + "</span><div><h3>" + $m.Groups[1].Value + "</h3><p>" + $m.Groups[2].Value + "</p></div></li>") })
  if ($pc.n -ne 5) { $bad.Add(('process steps=' + $pc.n)) }
  if (([regex]::Matches($t, '</div></li>\n  </div>\n</div></section>')).Count -ne 1) { $bad.Add('process-close count') }
  $t = $t -replace '</div></li>\n  </div>\n</div></section>', '</div></li>\n  </ol>\n</div></section>'

  # 6. Who boxes -> plain 3-col
  if (([regex]::Matches($t, '<div class="who-grid" data-stagger>')).Count -ne 1) { $bad.Add('who-grid count') }
  $t = $t -replace '<div class="who-grid" data-stagger>', '<div class="ed-who" data-stagger>'
  $hc = @{ n = 0 }
  $t = [regex]::Replace($t, '<article class="glass-card pillar(?: featured)? tiltable"><h3>(.*?)</h3><p>(.*?)</p><ul><li>\u2022 (.*?)</li><li>\u2022 (.*?)</li></ul></article>', { param($m) $hc.n++; ("<div class='ed-who-item'><small>" + $m.Groups[1].Value + "</small><p>" + $m.Groups[2].Value + "</p><ul><li>" + $m.Groups[3].Value + "</li><li>" + $m.Groups[4].Value + "</li></ul></div>") })
  if ($hc.n -ne 3) { $bad.Add(('who items=' + $hc.n)) }

  # 7. Dark deliverables box -> light editorial (keep .deliverables + .check-grid for JS)
  $oldInside = '  <div class="glass-card deliverables deliverables-dark" data-animate="fade-up">' + "`n" + '    <h2>' + "What's inside</h2>"
  $newInside = '  <div class="deliverables ed-inside" data-animate="fade-up">' + "`n" + '    <span class="section-label">Deliverables</span>' + "`n" + '    <h2>' + "What's inside</h2>"
  if (([regex]::Matches($t, [regex]::Escape($oldInside))).Count -ne 1) { $bad.Add('inside count') }
  $t = $t -replace [regex]::Escape($oldInside), $newInside

  # 8. CTA card box -> centered editorial (same depth, closers unchanged)
  $oldCta = '<section class="section final-cta"><div class="container"><div class="glass-card cta-card"><div class="cta-orb b"></div><div class="cta-orb g"></div>'
  $newCta = '<section class="section final-cta ed-cta"><div class="container"><div class="cta-inner">'
  if (([regex]::Matches($t, [regex]::Escape($oldCta))).Count -ne 1) { $bad.Add('cta count') }
  $t = $t -replace [regex]::Escape($oldCta), $newCta

  # ---- verification ----
  $gone = @('kpis-row', 'duo-grid', 'glass-card duo', 'duo-sub', 'section band', '"pillars"', 'icon-box', 'who-grid', 'glass-card pillar', 'deliverables-dark', 'cta-card', 'cta-orb', '<div class="step">', '<div class="num">', '<div class="process"')
  foreach ($g in $gone) { if ($t.Contains($g)) { $bad.Add(('stale: ' + $g)) } }
  if ($t.Contains([char]0x2022 + ' ')) { $bad.Add('stale: bullet') }
  $need = @('svc-meta', 'svc-duo', 'ed-list', 'ed-steps', 'ed-who', 'ed-inside', 'ed-cta', 'svc-card', 'faq-item', 'svc-side', 'style.css?v=14', 'check-grid', 'deliverables')
  foreach ($g in $need) { if (-not $t.Contains($g)) { $bad.Add(('missing: ' + $g)) } }
  foreach ($m in [regex]::Matches($t, 'glass-card')) {
    $ls = $t.LastIndexOf("`n", $m.Index); if ($ls -lt 0) { $ls = 0 }
    $le = $t.IndexOf("`n", $m.Index); if ($le -lt 0) { $le = $t.Length }
    $line = $t.Substring($ls, $le - $ls)
    if (-not ($line.Contains('svc-card') -or $line.Contains('svc-side') -or $line.Contains('modal'))) { $bad.Add('unexpected glass-card'); break }
  }

  if ($bad.Count -gt 0) { foreach ($b in $bad) { $errors.Add(($short + ' : ' + $b)) }; continue }
  $out = $t -replace "`n", "`r`n"
  [System.IO.File]::WriteAllText($path, $out, (New-Object System.Text.UTF8Encoding $false))
  $changed++
}

Write-Output ('changed: ' + $changed + '/37')
if ($errors.Count -gt 0) { Write-Output 'ERRORS:'; foreach ($e in $errors) { Write-Output (' - ' + $e) }; exit 1 }
Write-Output 'OK: all 37 pages transformed, protected sections intact'

