input.content:
# Who-needs-this: move definition <p> into hover "?" popup (data-tip), 37 service pages.
$ErrorActionPreference = 'Stop'
$files = Get-ChildItem 'C:\Users\ishan\Website\services\*.html' | Sort-Object Name
if ($files.Count -ne 37) { throw ('expected 37, found ' + $files.Count) }
$pat = "<div class='ed-who-item'><small>(Startup|SME|Enterprise)</small><p>(.*?)</p><ul><li>(.*?)</li><li>(.*?)</li></ul></div>"
$changed = 0
$errors = @()
foreach ($f in $files) {
  $raw = [System.IO.File]::ReadAllBytes($f.FullName)
  $hadBom = ($raw.Length -ge 3 -and $raw[0] -eq 0xEF -and $raw[1] -eq 0xBB -and $raw[2] -eq 0xBF)
  $t = [System.IO.File]::ReadAllText($f.FullName)
  $c = @{ n = 0 }
  $t = [regex]::Replace($t, $pat, { param($m)
    $c.n++
    $d = $m.Groups[2].Value
    $d = [regex]::Replace($d, '&(?!(?:amp|lt|gt|quot|#\d+);)', '&amp;')
    $d = $d.Replace('"', '&quot;').Replace('<', '&lt;').Replace('>', '&gt;')
    ("<div class='ed-who-item'><small>" + $m.Groups[1].Value + " <span class='who-tip' tabindex='0' data-tip='" + $d + "'>?</span></small><ul><li>" + $m.Groups[3].Value + "</li><li>" + $m.Groups[4].Value + "</li></ul></div>")
  })
  if ($c.n -ne 3) { $errors += ($f.Name + ' : items=' + $c.n); continue }
  if (([regex]::Matches($t, "<small>(Startup|SME|Enterprise)</small><p>")).Count -ne 0) { $errors += ($f.Name + ' : stale definition <p> remains'); continue }
  if (([regex]::Matches($t, 'who-tip')).Count -ne 3) { $errors += ($f.Name + ' : who-tip count wrong'); continue }
  [System.IO.File]::WriteAllText($f.FullName, $t, (New-Object System.Text.UTF8Encoding $hadBom))
  $changed++
}
Write-Output ('changed: ' + $changed + '/37')
if ($errors.Count -gt 0) { foreach ($e in $errors) { Write-Output ('ERROR: ' + $e) }; exit 1 }
Write-Output 'OK'

