input.content:
# Deliverables: checklist -> 4 hover-flip boxes (37 service pages).
$ErrorActionPreference = 'Stop'
$files = Get-ChildItem 'C:\Users\ishan\Website\services\*.html' | Sort-Object Name
if ($files.Count -ne 37) { throw ('expected 37, found ' + $files.Count) }
$pairPat = '<li class="grphead">(.*?):</li>\s*<li><i data-lucide="check"></i>(.*?)</li>'
$blockPat = '(?s)<ul class="check-grid" data-stagger>.*?</ul>'
$changed = 0
$errors = @()
foreach ($f in $files) {
  $raw = [System.IO.File]::ReadAllBytes($f.FullName)
  $hadBom = ($raw.Length -ge 3 -and $raw[0] -eq 0xEF -and $raw[1] -eq 0xBB -and $raw[2] -eq 0xBF)
  $t = [System.IO.File]::ReadAllText($f.FullName)
  $pairs = [regex]::Matches($t, $pairPat)
  if ($pairs.Count -ne 4) { $errors += ($f.Name + ' : groups=' + $pairs.Count); continue }
  if (([regex]::Matches($t, $blockPat)).Count -ne 1) { $errors += ($f.Name + ' : check-grid block != 1'); continue }
  $n = 0
  $cards = ''
  foreach ($p in $pairs) {
    $n++
    $nn = '{0:D2}' -f $n
