input.content:
# Process+Why columns -> tile treatment (37 service pages).
$ErrorActionPreference = 'Stop'
$files = Get-ChildItem 'C:\Users\ishan\Website\services\*.html' | Sort-Object Name
if ($files.Count -ne 37) { throw ('expected 37, found ' + $files.Count) }
$changed = 0
$errors = @()
foreach ($f in $files) {
  $raw = [System.IO.File]::ReadAllBytes($f.FullName)
  $hadBom = ($raw.Length -ge 3 -and $raw[0] -eq 0xEF -and $raw[1] -eq 0xBB -and $raw[2] -eq 0xBF)
  $t = [System.IO.File]::ReadAllText($f.FullName)
  $t = $t -replace "`r`n", "`n"

  if (([regex]::Matches($t, '<div class="ed-split">')).Count -ne 1) { $errors += ($f.Name + ' : ed-split != 1'); continue }
  $t = $t -replace '<div class="ed-split">', '<div class="ed-split ed-tiles">'

  if (([regex]::Matches($t, '      <ol class="ed-steps" data-stagger>')).Count -ne 1) { $errors += ($f.Name + ' : steps open != 1'); continue }
  $t = $t -replace '      <ol class="ed-steps" data-stagger>', ('      <div class="tile tile-main">' + "`n" + '      <ol class="ed-steps tile-steps" data-stagger>')

  if (([regex]::Matches($t, "      </ol>`n    </div>`n    <div class=`"ed-split-side`">")).Count -ne 1) { $errors += ($f.Name + ' : steps close != 1'); continue }
  $t = $t -replace "      </ol>`n    </div>`n    <div class=`"ed-split-side`">", ("      </ol>`n      </div>`n    </div>`n    <div class=`"ed-split-side`">")

  $whyLis = [regex]::Matches($t, "<li><span class='ed-num'>\d+</span><div><h3>(.*?)</h3><p>(.*?)</p></div></li>")
  if ($whyLis.Count -ne 3) { $errors += ($f.Name + ' : why items=' + $whyLis.Count); continue }
  $tiles = ''
  foreach ($w in $whyLis) {
    $tiles += ('      <div class=' + "'tile tile-why'><h3>" + $w.Groups[1].Value + '</h3><p>' + $w.Groups[2].Value + '</p></div>' + "`n")
  }
  $tiles = $tiles.TrimEnd("`r", "`n")
  if (([regex]::Matches($t, '(?s)      <ol class="ed-list" data-stagger>.*?-list-x')).Count -ne 0) { $errors += ($f.Name + ' : sentinel'); continue }
  $t = [regex]::Replace($t, '(?s)      <ol class="ed-list" data-stagger>.*?\n      </ol>', { param($mm) return $script:tilesBlock })
  $script:tilesBlock = ('      <div class="tile-grid">' + "`n" + $tiles + "`n" + '      </div>')

  if (([regex]::Matches($t, 'tile tile-why')).Count -ne 3) { $errors += ($f.Name + ' : why tiles wrong'); continue }
  if (([regex]::Matches($t, 'tile tile-main')).Count -ne 1) { $errors += ($f.Name + ' : main tile wrong'); continue }
  if ($t.Contains('ed-list')) { $errors += ($f.Name + ' : stale ed-list remains'); continue }
  $t = $t -replace "`n", "`r`n"
  [System.IO.File]::WriteAllText($f.FullName, $t, (New-Object System.Text.UTF8Encoding $hadBom))
  $changed++
}
Write-Output ('tiled: ' + $changed + '/37')
if ($errors.Count -gt 0) { foreach ($e in $errors) { Write-Output ('ERROR: ' + $e) }; exit 1 }
Write-Output 'OK'

